81	/// Python type provider extracting class, function, and type alias definitions
82	/// from tree-sitter ASTs using PEP 484 type annotations.
83	///
84	/// Uses `Arc<PythonTypeData>` for efficient cloning when registered in the
85	/// TypeRegistry.
86	#[derive(Clone)]
87	pub struct PythonTypeProvider {
88	    pub data: Arc<PythonTypeData>,
89	}
