91	impl PythonTypeProvider {
92	    /// Build a PythonTypeProvider by scanning all Python parsed files.
93	    pub fn from_parsed_files(files: &BTreeMap<String, ParsedFile>) -> Self {
94	        let mut inner = PythonTypeData {
95	            classes: BTreeMap::new(),
96	            functions: BTreeMap::new(),
97	            aliases: BTreeMap::new(),
98	        };
99	
100	        for (path, parsed) in files {
101	            if parsed.language != Language::Python {
102	                continue;
103	            }
104	            Self::extract_from_file(&mut inner, path, parsed);
105	        }
106	
107	        PythonTypeProvider {
108	            data: Arc::new(inner),
109	        }
110	    }
