112	    // -----------------------------------------------------------------------
113	    // AST extraction
114	    // -----------------------------------------------------------------------
115	
116	    fn extract_from_file(data: &mut PythonTypeData, path: &str, parsed: &ParsedFile) {
117	        let root = parsed.tree.root_node();
118	        let mut cursor = root.walk();
119	
120	        for child in root.children(&mut cursor) {
121	            Self::extract_top_level(data, &child, path, parsed);
122	        }
123	    }
124	
125	    fn extract_top_level(
126	        data: &mut PythonTypeData,
127	        node: &tree_sitter::Node,
128	        path: &str,
129	        parsed: &ParsedFile,
130	    ) {
131	        match node.kind() {
132	            "class_definition" => {
133	                Self::extract_class(data, node, path, parsed, false);
134	            }
135	            "function_definition" => {
136	                Self::extract_function(data, node, path, parsed);
137	            }
138	            "decorated_definition" => {
139	                Self::extract_decorated(data, node, path, parsed);
140	            }
141	            "expression_statement" => {
142	                // Type aliases: `MyType: TypeAlias = int` or `MyType = int`
143	                Self::try_extract_type_alias(data, node, parsed);
144	            }
145	            _ => {}
146	        }
147	    }
148	
149	    /// Extract a decorated definition — unwraps decorators and delegates to
150	    /// class or function extraction.
151	    fn extract_decorated(
152	        data: &mut PythonTypeData,
153	        node: &tree_sitter::Node,
154	        path: &str,
155	        parsed: &ParsedFile,
156	    ) {
157	        let is_dataclass = Self::has_decorator(node, parsed, "dataclass");
158	
159	        // The actual definition is the last named child (class or function).
160	        if let Some(definition) = node.child_by_field_name("definition") {
161	            match definition.kind() {
162	                "class_definition" => {
163	                    Self::extract_class(data, &definition, path, parsed, is_dataclass);
164	                }
165	                "function_definition" => {
166	                    Self::extract_function(data, &definition, path, parsed);
167	                }
168	                _ => {}
169	            }
170	        }
171	    }
