173	    /// Check if a decorated_definition has a specific decorator name.
174	    fn has_decorator(node: &tree_sitter::Node, parsed: &ParsedFile, name: &str) -> bool {
175	        let mut cursor = node.walk();
176	        for child in node.children(&mut cursor) {
177	            if child.kind() == "decorator" {
178	                let text = parsed.node_text(&child).trim().to_string();
179	                // @dataclass or @dataclass(...) or @dataclasses.dataclass
180	                if text.starts_with('@') {
181	                    let decorator_name = text[1..]
182	                        .split('(')
183	                        .next()
184	                        .unwrap_or("")
185	                        .split('.')
186	                        .last()
187	                        .unwrap_or("");
188	                    if decorator_name == name {
189	                        return true;
190	                    }
191	                }
192	            }
193	        }
194	        false
195	    }
