197	    /// Extract a class definition.
198	    fn extract_class(
199	        data: &mut PythonTypeData,
200	        node: &tree_sitter::Node,
201	        path: &str,
202	        parsed: &ParsedFile,
203	        is_dataclass: bool,
204	    ) {
205	        let name = match node.child_by_field_name("name") {
206	            Some(n) => parsed.node_text(&n).trim().to_string(),
207	            None => return,
208	        };
209	        if name.is_empty() {
210	            return;
211	        }
212	
213	        let line = node.start_position().row + 1;
214	        let bases = Self::extract_bases(node, parsed);
215	        let (attributes, methods) = Self::extract_class_body(node, parsed);
216	
217	        data.classes.insert(
218	            name.clone(),
219	            PythonClass {
220	                name,
221	                bases,
222	                attributes,
223	                methods,
224	                is_dataclass,
225	                file: path.to_string(),
226	                line,
227	            },
228	        );
229	    }
