231	    /// Extract base classes from `class Foo(Base1, Base2):`.
232	    fn extract_bases(node: &tree_sitter::Node, parsed: &ParsedFile) -> Vec<String> {
233	        let mut bases = Vec::new();
234	
235	        let superclasses = match node.child_by_field_name("superclasses") {
236	            Some(s) => s,
237	            None => return bases,
238	        };
239	
240	        // superclasses is an argument_list node containing identifiers.
241	        let mut cursor = superclasses.walk();
242	        for child in superclasses.children(&mut cursor) {
243	            match child.kind() {
244	                "identifier" | "attribute" => {
245	                    let text = parsed.node_text(&child).trim().to_string();
246	                    if !text.is_empty() {
247	                        bases.push(text);
248	                    }
249	                }
250	                // Handle generic bases like Protocol[T] — extract the base name.
251	                "subscript" => {
252	                    if let Some(value) = child.child_by_field_name("value") {
253	                        let text = parsed.node_text(&value).trim().to_string();
254	                        if !text.is_empty() {
255	                            bases.push(text);
256	                        }
257	                    }
258	                }
259	                _ => {}
260	            }
261	        }
262	
263	        bases
264	    }
