266	    /// Extract annotated attributes and methods from a class body.
267	    fn extract_class_body(
268	        node: &tree_sitter::Node,
269	        parsed: &ParsedFile,
270	    ) -> (BTreeMap<String, String>, BTreeMap<String, String>) {
271	        let mut attributes = BTreeMap::new();
272	        let mut methods = BTreeMap::new();
273	
274	        let body = match node.child_by_field_name("body") {
275	            Some(b) => b,
276	            None => return (attributes, methods),
277	        };
278	
279	        let mut cursor = body.walk();
280	        for child in body.children(&mut cursor) {
281	            match child.kind() {
282	                "expression_statement" => {
283	                    // Annotated attribute: `name: str`
284	                    Self::try_extract_annotation(&child, parsed, &mut attributes);
285	                }
286	                "function_definition" => {
287	                    if let Some(name_node) = child.child_by_field_name("name") {
288	                        let method_name = parsed.node_text(&name_node).trim().to_string();
289	                        if !method_name.is_empty() {
290	                            let sig = Self::build_fn_signature(&child, parsed);
291	                            methods.insert(method_name, sig);
292	                        }
293	                    }
294	                }
295	                "decorated_definition" => {
296	                    // Decorated method (e.g., @staticmethod, @classmethod, @property).
297	                    if let Some(definition) = child.child_by_field_name("definition") {
298	                        if definition.kind() == "function_definition" {
299	                            if let Some(name_node) = definition.child_by_field_name("name") {
300	                                let method_name = parsed.node_text(&name_node).trim().to_string();
301	                                if !method_name.is_empty() {
302	                                    let sig = Self::build_fn_signature(&definition, parsed);
303	                                    methods.insert(method_name, sig);
304	                                }
305	                            }
306	                        }
307	                    }
308	                }
309	                _ => {}
310	            }
311	        }
312	
313	        (attributes, methods)
314	    }
