316	    /// Try to extract a type annotation from an expression_statement.
317	    /// Handles both bare annotations (`name: str`) and annotated assignments
318	    /// (`name: str = "default"`). tree-sitter-python represents both as
319	    /// `assignment` nodes with a `type` field — the `left` field holds the
320	    /// identifier, and `right` (if present) holds the default value.
321	    fn try_extract_annotation(
322	        node: &tree_sitter::Node,
323	        parsed: &ParsedFile,
324	        attrs: &mut BTreeMap<String, String>,
325	    ) {
326	        let mut cursor = node.walk();
327	        for child in node.children(&mut cursor) {
328	            if child.kind() == "assignment" {
329	                if let Some(type_node) = child.child_by_field_name("type") {
330	                    if let Some(left) = child.child_by_field_name("left") {
331	                        let name = parsed.node_text(&left).trim().to_string();
332	                        let type_str = parsed.node_text(&type_node).trim().to_string();
333	                        if !name.is_empty() && !type_str.is_empty() {
334	                            attrs.insert(name, type_str);
335	                        }
336	                    }
337	                }
338	            }
339	        }
340	    }
