342	    /// Try to extract a type alias from a top-level expression_statement.
343	    /// Handles: `MyType = int` or `MyType: TypeAlias = int`.
344	    fn try_extract_type_alias(
345	        data: &mut PythonTypeData,
346	        node: &tree_sitter::Node,
347	        parsed: &ParsedFile,
348	    ) {
349	        let mut cursor = node.walk();
350	        for child in node.children(&mut cursor) {
351	            if child.kind() == "assignment" {
352	                // Check if this looks like a type alias:
353	                // - `MyType: TypeAlias = SomeType`
354	                // - `MyType = SomeType` where SomeType starts with uppercase
355	                let left = match child.child_by_field_name("left") {
356	                    Some(l) => l,
357	                    None => continue,
358	                };
359	                let right = match child.child_by_field_name("right") {
360	                    Some(r) => r,
361	                    None => continue,
362	                };
363	
364	                let name = parsed.node_text(&left).trim().to_string();
365	                let target = parsed.node_text(&right).trim().to_string();
366	
367	                if name.is_empty() || target.is_empty() {
368	                    continue;
369	                }
370	
371	                // Check for explicit TypeAlias annotation.
372	                if let Some(type_node) = child.child_by_field_name("type") {
373	                    let annotation = parsed.node_text(&type_node).trim().to_string();
374	                    if annotation == "TypeAlias" {
375	                        data.aliases.insert(name, target);
376	                        return;
377	                    }
378	                }
379	
380	                // Heuristic: `Name = OtherName` where both start uppercase
381	                // and the RHS is a simple type expression (identifier, subscript,
382	                // or attribute).
383	                if name.starts_with(|c: char| c.is_ascii_uppercase())
384	                    && matches!(right.kind(), "identifier" | "subscript" | "attribute")
385	                {
386	                    let first_char_upper = target.starts_with(|c: char| c.is_ascii_uppercase());
387	                    if first_char_upper {
388	                        data.aliases.insert(name, target);
389	                    }
390	                }
391	            }
392	        }
393	    }
