395	    /// Build a function signature string from parameters and return type.
396	    fn build_fn_signature(node: &tree_sitter::Node, parsed: &ParsedFile) -> String {
397	        let mut parts = Vec::new();
398	
399	        if let Some(params) = node.child_by_field_name("parameters") {
400	            parts.push(parsed.node_text(&params).trim().to_string());
401	        }
402	
403	        if let Some(ret) = node.child_by_field_name("return_type") {
404	            let ret_text = parsed.node_text(&ret).trim().to_string();
405	            parts.push(format!("-> {}", ret_text));
406	        }
407	
408	        parts.join(" ")
409	    }
