411	    /// Extract a top-level function definition.
412	    fn extract_function(
413	        data: &mut PythonTypeData,
414	        node: &tree_sitter::Node,
415	        path: &str,
416	        parsed: &ParsedFile,
417	    ) {
418	        let name = match node.child_by_field_name("name") {
419	            Some(n) => parsed.node_text(&n).trim().to_string(),
420	            None => return,
421	        };
422	        if name.is_empty() {
423	            return;
424	        }
425	
426	        let line = node.start_position().row + 1;
427	        let params = Self::extract_typed_params(node, parsed);
428	        let return_type = node
429	            .child_by_field_name("return_type")
430	            .map(|rt| parsed.node_text(&rt).trim().to_string())
431	            .filter(|s| !s.is_empty());
432	
433	        data.functions.insert(
434	            name.clone(),
435	            PythonFunction {
436	                name,
437	                params,
438	                return_type,
439	                file: path.to_string(),
440	                line,
441	            },
442	        );
443	    }
