445	    /// Extract typed parameters from a function's parameter list.
446	    fn extract_typed_params(
447	        node: &tree_sitter::Node,
448	        parsed: &ParsedFile,
449	    ) -> BTreeMap<String, String> {
450	        let mut params = BTreeMap::new();
451	
452	        let parameters = match node.child_by_field_name("parameters") {
453	            Some(p) => p,
454	            None => return params,
455	        };
456	
457	        let mut cursor = parameters.walk();
458	        for child in parameters.children(&mut cursor) {
459	            match child.kind() {
460	                "typed_parameter" | "typed_default_parameter" => {
461	                    let param_name = child
462	                        .child_by_field_name("name")
463	                        .map(|n| parsed.node_text(&n).trim().to_string());
464	                    let param_type = child
465	                        .child_by_field_name("type")
466	                        .map(|t| parsed.node_text(&t).trim().to_string());
467	
468	                    if let (Some(name), Some(type_str)) = (param_name, param_type) {
469	                        if !name.is_empty()
470	                            && !type_str.is_empty()
471	                            && name != "self"
472	                            && name != "cls"
473	                        {
474	                            params.insert(name, type_str);
475	                        }
476	                    }
477	                }
478	                _ => {}
479	            }
480	        }
481	
482	        params
483	    }
