485	    /// Collect all methods from a class and its base classes (MRO approximation).
486	    /// Uses visited set for cycle protection.
487	    fn collect_methods_with_bases(
488	        data: &PythonTypeData,
489	        class_name: &str,
490	        visited: &mut std::collections::BTreeSet<String>,
491	    ) -> BTreeMap<String, String> {
492	        if !visited.insert(class_name.to_string()) {
493	            return BTreeMap::new();
494	        }
495	
496	        let mut methods = BTreeMap::new();
497	
498	        if let Some(cls) = data.classes.get(class_name) {
499	            // Base class methods first (overridden by child).
500	            for base in &cls.bases {
501	                let base_methods = Self::collect_methods_with_bases(data, base, visited);
502	                methods.extend(base_methods);
503	            }
504	            // Child methods override base.
505	            methods.extend(cls.methods.clone());
506	        }
507	
508	        methods
509	    }
510	
511	    /// Collect all attributes from a class and its base classes.
512	    fn collect_attrs_with_bases(
513	        data: &PythonTypeData,
514	        class_name: &str,
515	        visited: &mut std::collections::BTreeSet<String>,
516	    ) -> BTreeMap<String, String> {
517	        if !visited.insert(class_name.to_string()) {
518	            return BTreeMap::new();
519	        }
520	
521	        let mut attrs = BTreeMap::new();
522	
523	        if let Some(cls) = data.classes.get(class_name) {
524	            for base in &cls.bases {
525	                let base_attrs = Self::collect_attrs_with_bases(data, base, visited);
526	                attrs.extend(base_attrs);
527	            }
528	            attrs.extend(cls.attributes.clone());
529	        }
530	
531	        attrs
532	    }
533	}
