539	impl TypeProvider for PythonTypeProvider {
540	    fn resolve_type(&self, _file: &str, expr: &str, _line: usize) -> Option<ResolvedType> {
541	        if self.data.classes.contains_key(expr) {
542	            return Some(ResolvedType {
543	                name: expr.to_string(),
544	                kind: ResolvedTypeKind::Concrete,
545	                type_params: Vec::new(),
546	            });
547	        }
548	        if let Some(target) = self.data.aliases.get(expr) {
549	            return Some(ResolvedType {
550	                name: target.clone(),
551	                kind: ResolvedTypeKind::Alias,
552	                type_params: Vec::new(),
553	            });
554	        }
555	        None
556	    }
557	
558	    fn field_layout(&self, type_name: &str) -> Option<Vec<TypeFieldInfo>> {
559	        if let Some(_cls) = self.data.classes.get(type_name) {
560	            let mut fields = Vec::new();
561	
562	            // Annotated attributes (including inherited).
563	            let all_attrs = Self::collect_attrs_with_bases(
564	                &self.data,
565	                type_name,
566	                &mut std::collections::BTreeSet::new(),
567	            );
568	            for (name, type_str) in &all_attrs {
569	                fields.push(TypeFieldInfo {
570	                    name: name.clone(),
571	                    type_str: type_str.clone(),
572	                });
573	            }
574	
575	            // Methods (including inherited), excluding dunder methods.
576	            let all_methods = Self::collect_methods_with_bases(
577	                &self.data,
578	                type_name,
579	                &mut std::collections::BTreeSet::new(),
580	            );
581	            for (name, sig) in &all_methods {
582	                if !name.starts_with("__") {
583	                    fields.push(TypeFieldInfo {
584	                        name: name.clone(),
585	                        type_str: sig.clone(),
586	                    });
587	                }
588	            }
589	
590	            return Some(fields);
591	        }
592	
593	        None
