import ast, os, sys, json
from collections import defaultdict

def iter_py_files(root, excludes):
    for dirpath, dirnames, filenames in os.walk(root):
        rel = os.path.relpath(dirpath, root)
        # prune excluded dirs
        parts = rel.split(os.sep) if rel != '.' else []
        skip = False
        for exc in excludes:
            exc_dir = exc.rstrip('/*')
            if exc_dir in parts or (rel != '.' and rel.startswith(exc_dir)):
                skip = True
        if skip:
            dirnames[:] = []
            continue
        dirnames[:] = [d for d in dirnames if d not in ('.venv', '__pycache__', '.git')]
        for f in filenames:
            if f.endswith('.py'):
                yield os.path.join(dirpath, f)

class ClassInfo:
    def __init__(self, name, bases, file, lineno):
        self.name = name
        self.bases = bases  # list of base name strings (dotted attr collapsed to last segment for simplicity, kept full too)
        self.file = file
        self.lineno = lineno
        self.methods = set()

def base_name_str(node):
    # returns a reasonably faithful string for the base expr
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        return node.attr  # last segment, e.g. models.Model -> Model
    if isinstance(node, ast.Subscript):
        return base_name_str(node.value)
    if isinstance(node, ast.Call):
        return None
    return None

def analyze_repo(root, excludes, label):
    classes = {}  # name -> list[ClassInfo] (name collisions possible)
    file_imports = defaultdict(dict)  # file -> {local_name: module_str}
    all_files = list(iter_py_files(root, excludes))
    trees = {}
    for path in all_files:
        try:
            with open(path, 'r', encoding='utf-8', errors='replace') as fh:
                src = fh.read()
            tree = ast.parse(src, filename=path)
            trees[path] = tree
        except SyntaxError:
            continue

    # pass 1: imports + class registry
    for path, tree in trees.items():
        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom):
                mod = node.module or ''
                is_external = node.level == 0 and not (mod.split('.')[0] == os.path.basename(root).replace('-', '_'))
                for alias in node.names:
                    local = alias.asname or alias.name
                    file_imports[path][local] = {'module': mod, 'external': is_external, 'level': node.level}
            elif isinstance(node, ast.Import):
                for alias in node.names:
                    local = alias.asname or alias.name.split('.')[0]
                    is_external = alias.name.split('.')[0] != os.path.basename(root).replace('-', '_')
                    file_imports[path][local] = {'module': alias.name, 'external': is_external, 'level': 0}

    for path, tree in trees.items():
        for node in ast.walk(tree):
            if isinstance(node, ast.ClassDef):
                bases = [base_name_str(b) for b in node.bases]
                bases = [b for b in bases if b]
                ci = ClassInfo(node.name, bases, path, node.lineno)
                for stmt in node.body:
                    if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):
                        ci.methods.add(stmt.name)
                classes.setdefault(node.name, []).append(ci)

    # pass 2: find self.X() calls inside methods, classify
    own_hit = 0        # resolved by 1a (own class defines it) -- for reference only
    inherited_inrepo = 0   # 1b target: found on an in-repo base, not on own class
    inherited_external = 0  # base is external (import says so, or base name not found in-repo)
    inherited_ambiguous_branch = 0  # found on >1 distinct branch among multiple bases
    samples_inrepo = []
    samples_external = []
    samples_ambiguous = []

    def resolve_base_in_repo(file, base_name):
        """Return list of ClassInfo candidates for base_name that are plausibly
        in-repo AND not shadowed by an external import of the same local name."""
        imp = file_imports.get(file, {}).get(base_name)
        if imp is not None and imp['external'] and imp['level'] == 0:
            return None  # explicitly imported from an external package -> external
        return classes.get(base_name)

    def walk_branch(file, base_name, target_method, visited):
        """DFS a single base's chain (that base + its own bases) looking for
        target_method. Returns the defining ClassInfo or None. `visited` guards
        cycles across the whole search (shared across branches at this call)."""
        cands = resolve_base_in_repo(file, base_name)
        if not cands:
            return 'EXTERNAL'
        found = None
        for c in cands:
            key = (c.file, c.name, c.lineno)
            if key in visited:
                continue
            visited.add(key)
            if target_method in c.methods:
                found = c
                break
            for b in c.bases:
                r = walk_branch(c.file, b, target_method, visited)
                if r == 'EXTERNAL':
                    continue
                if r is not None:
                    found = r
                    break
            if found:
                break
        return found

    for path, tree in trees.items():
        for node in ast.walk(tree):
            if not isinstance(node, ast.ClassDef):
                continue
            if not node.bases:
                continue
            cis = [c for c in classes.get(node.name, []) if c.file == path and c.lineno == node.lineno]
            if not cis:
                continue
            ci = cis[0]
            for stmt in ast.walk(node):
                if isinstance(stmt, ast.Call) and isinstance(stmt.func, ast.Attribute):
                    if isinstance(stmt.func.value, ast.Name) and stmt.func.value.id == 'self':
                        method = stmt.func.attr
                        if method in ci.methods:
                            own_hit += 1
                            continue
                        # not on own class -- check bases
                        branch_hits = []
                        any_external = False
                        for b in ci.bases:
                            r = walk_branch(path, b, method, set())
                            if r == 'EXTERNAL':
                                any_external = True
                            elif r is not None:
                                branch_hits.append((b, r))
                        distinct = {(r.file, r.name, r.lineno) for _, r in branch_hits}
                        if len(distinct) >= 2:
                            inherited_ambiguous_branch += 1
                            if len(samples_ambiguous) < 8:
                                samples_ambiguous.append(f"{path}:{node.lineno} class {ci.name} -> self.{method}() branches={branch_hits}")
                        elif len(distinct) == 1:
                            inherited_inrepo += 1
                            if len(samples_inrepo) < 15:
                                b, r = branch_hits[0]
                                samples_inrepo.append(f"{path}:{stmt.lineno} class {ci.name}(bases={ci.bases}) self.{method}() -> found on {r.name} @ {r.file}:{r.lineno}")
                        else:
                            inherited_external += 1
                            if len(samples_external) < 15:
                                samples_external.append(f"{path}:{stmt.lineno} class {ci.name}(bases={ci.bases}) self.{method}() -> NOT found in-repo (external base or unknown method)")

    print(f"=== {label} ===")
    print(f"files analyzed: {len(trees)}")
    print(f"classes with bases: {sum(1 for v in classes.values() for c in v if c.bases)}")
    print(f"self.X() resolved by OWN class (1a territory): {own_hit}")
    print(f"self.X() resolved via IN-REPO base (1b target):  {inherited_inrepo}")
    print(f"self.X() base external / method not found:       {inherited_external}")
    print(f"self.X() ambiguous (>1 distinct branch):          {inherited_ambiguous_branch}")
    print("--- in-repo samples ---")
    for s in samples_inrepo:
        print("  " + s)
    print("--- ambiguous samples ---")
    for s in samples_ambiguous:
        print("  " + s)
    print()
    return {
        'label': label, 'files': len(trees), 'own_hit': own_hit,
        'inherited_inrepo': inherited_inrepo, 'inherited_external': inherited_external,
        'inherited_ambiguous': inherited_ambiguous_branch,
    }

results = []
results.append(analyze_repo(os.path.expanduser('~/code/bench-repos/fastapi'), ['tests/*','docs_src/*','scripts/*','.venv/*'], 'fastapi'))
results.append(analyze_repo(os.path.expanduser('~/code/bench-repos/pydantic'), ['tests/*','docs/*','.venv/*'], 'pydantic'))

print(json.dumps(results, indent=2))

