import os, json
from collections import defaultdict
from tree_sitter import Language, Parser
import tree_sitter_typescript as tsts
import tree_sitter_javascript as tsjs

TS_LANG = Language(tsts.language_tsx())
JS_LANG = Language(tsjs.language())
ts_parser = Parser(TS_LANG)
js_parser = Parser(JS_LANG)

ROOT = os.path.expanduser('~/code/bench-repos/excalidraw')
EXCLUDE_DIRS = {'node_modules', '.git', 'dist', 'build', 'dev-docs', 'public', 'examples'}
EXCLUDE_SUBSTR = ['.test.', '.spec.', '/tests/']

def iter_files(root):
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in EXCLUDE_DIRS]
        for f in filenames:
            if f.endswith(('.ts', '.tsx')):
                p = os.path.join(dirpath, f)
                if any(s in p for s in EXCLUDE_SUBSTR):
                    continue
                yield p

def text(node, src):
    return src[node.start_byte:node.end_byte]

class ClassInfo:
    __slots__ = ('name','bases','file','line','methods')
    def __init__(self, name, bases, file, line):
        self.name = name; self.bases = bases; self.file = file; self.line = line
        self.methods = set()

classes = defaultdict(list)  # name -> [ClassInfo]
file_imports = defaultdict(dict)  # file -> {local_name: {module, external}}
trees = {}

files = list(iter_files(ROOT))
for path in files:
    with open(path, 'r', encoding='utf-8', errors='replace') as fh:
        src = fh.read()
    b = src.encode('utf-8')
    tree = ts_parser.parse(b)
    trees[path] = (tree, b)

def walk(node):
    yield node
    for c in node.children:
        yield from walk(c)

# pass 1: imports
for path, (tree, b) in trees.items():
    for node in walk(tree.root_node):
        if node.type == 'import_statement':
            src_node = node.child_by_field_name('source')
            module = text(src_node, b).strip('"\'') if src_node else ''
            external = not module.startswith('.')
            # named imports / default import / namespace
            for c in walk(node):
                if c.type == 'import_specifier':
                    name_node = c.child_by_field_name('name')
                    alias_node = c.child_by_field_name('alias')
                    local = text(alias_node, b) if alias_node else (text(name_node, b) if name_node else None)
                    if local:
                        file_imports[path][local] = {'module': module, 'external': external}
                elif c.type == 'identifier' and c.parent and c.parent.type in ('import_clause',):
                    local = text(c, b)
                    file_imports[path][local] = {'module': module, 'external': external}

# pass 2: classes
for path, (tree, b) in trees.items():
    for node in walk(tree.root_node):
        if node.type == 'class_declaration':
            name_node = node.child_by_field_name('name')
            if not name_node:
                continue
            name = text(name_node, b)
            bases = []
            for c in node.children:
                if c.type == 'class_heritage':
                    for hc in walk(c):
                        if hc.type == 'extends_clause':
                            val = hc.child_by_field_name('value')
                            if val is None and hc.named_child_count > 0:
                                val = hc.named_children[0]
                            if val is not None:
                                base_text = text(val, b)
                                base_name = base_text.split('<')[0].split('.')[-1].strip()
                                if base_name:
                                    bases.append(base_name)
            ci = ClassInfo(name, bases, path, node.start_point[0] + 1)
            body = node.child_by_field_name('body')
            if body:
                for m in body.children:
                    if m.type == 'method_definition':
                        mname_node = m.child_by_field_name('name')
                        if mname_node:
                            ci.methods.add(text(mname_node, b))
            classes[name].append(ci)

def resolve_base_in_repo(file, base_name):
    imp = file_imports.get(file, {}).get(base_name)
    if imp is not None and imp['external']:
        return None
    return classes.get(base_name)

def walk_branch(file, base_name, target_method, visited):
    cands = resolve_base_in_repo(file, base_name)
    if not cands:
        return 'EXTERNAL'
    found = None
    for c in cands:
        key = (c.file, c.name, c.line)
        if key in visited:
            continue
        visited.add(key)
        if target_method in c.methods:
            found = c
            break
        for bb in c.bases:
            r = walk_branch(c.file, bb, target_method, visited)
            if r == 'EXTERNAL':
                continue
            if r is not None:
                found = r
                break
        if found:
