import ast, os
from collections import defaultdict

def iter_py_files(root, excludes):
    for dirpath, dirnames, filenames in os.walk(root):
        rel = os.path.relpath(dirpath, root)
        parts = rel.split(os.sep) if rel != '.' else []
        skip = False
        for exc in excludes:
            exc_dir = exc.rstrip('/*')
            if exc_dir in parts or (rel != '.' and rel.startswith(exc_dir)):
                skip = True
        if skip:
            dirnames[:] = []
            continue
        dirnames[:] = [d for d in dirnames if d not in ('.venv', '__pycache__', '.git')]
        for f in filenames:
            if f.endswith('.py'):
                yield os.path.join(dirpath, f)

class ClassInfo:
    def __init__(self, name, bases, file, lineno):
        self.name = name; self.bases = bases; self.file = file; self.lineno = lineno
        self.methods = set()

def base_name_str(node):
    if isinstance(node, ast.Name): return node.id
    if isinstance(node, ast.Attribute): return node.attr
    if isinstance(node, ast.Subscript): return base_name_str(node.value)
    return None

def analyze(root, excludes, label):
    classes = {}
    trees = {}
    for path in iter_py_files(root, excludes):
        try:
            src = open(path, encoding='utf-8', errors='replace').read()
            trees[path] = ast.parse(src, filename=path)
        except SyntaxError:
            continue
    for path, tree in trees.items():
        for node in ast.walk(tree):
            if isinstance(node, ast.ClassDef):
                bases = [b for b in (base_name_str(x) for x in node.bases) if b]
                ci = ClassInfo(node.name, bases, path, node.lineno)
                for stmt in node.body:
                    if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):
                        ci.methods.add(stmt.name)
                classes.setdefault(node.name, []).append(ci)

    same_file_hits = 0
    cross_file_hits = 0
    single_base_hits = 0
    multi_base_hits = 0

    def walk_branch(file, base_name, target_method, visited):
        cands = classes.get(base_name)
        if not cands: return None
        for c in cands:
            key=(c.file,c.name,c.lineno)
            if key in visited: continue
            visited.add(key)
            if target_method in c.methods: return c
            for b in c.bases:
                r = walk_branch(c.file, b, target_method, visited)
                if r: return r
        return None

    for path, tree in trees.items():
        for node in ast.walk(tree):
            if not isinstance(node, ast.ClassDef) or not node.bases: continue
            cis = [c for c in classes.get(node.name, []) if c.file==path and c.lineno==node.lineno]
            if not cis: continue
            ci = cis[0]
            for stmt in ast.walk(node):
                if isinstance(stmt, ast.Call) and isinstance(stmt.func, ast.Attribute) and isinstance(stmt.func.value, ast.Name) and stmt.func.value.id=='self':
                    method = stmt.func.attr
                    if method in ci.methods: continue
                    hits = []
                    for b in ci.bases:
                        r = walk_branch(path, b, method, set())
                        if r: hits.append(r)
                    distinct = {(r.file,r.name,r.lineno) for r in hits}
                    if len(distinct)==1:
                        r = hits[0]
                        if r.file == path:
                            same_file_hits += 1
                        else:
                            cross_file_hits += 1
                            print(f"CROSS-FILE hit: {path}:{stmt.lineno} class {ci.name} self.{method}() -> {r.name} @ {r.file}:{r.lineno}")
                        if len(ci.bases) == 1:
                            single_base_hits += 1
                        else:
                            multi_base_hits += 1
                            print(f"MULTI-BASE hit: {path}:{stmt.lineno} class {ci.name}(bases={ci.bases})")
    print(f"{label}: same_file={same_file_hits} cross_file={cross_file_hits} single_base={single_base_hits} multi_base={multi_base_hits}")

